import pytest
from ruamel.yaml import YAML

from app.dbt.schema_unit_tests import add_unit_test, flow_row, replace_expect_rows
from app.dbt.schema_yaml import SchemaYamlError

ITEM = {
    "name": "orders_state",
    "model": "orders",
    "description": "Generated by wickd",
    "given": [
        {"input": "ref('raw_orders')", "rows": [{"id": 1, "status": "completed", "day": "2024-01-01"}],
         "format": "dict"},
        {"input": "source('shop', 'customers')", "rows": [], "format": "dict"},
    ],
    "expect": {"rows": [{"id": 1, "state": "done", "amount": 3.5, "ok": True, "note": None}], "format": "dict"},
}

SCHEMA = """version: 2

models:
  - name: orders
    description: Orders
    columns:
      - name: id
        data_tests:
          - unique
"""


def _load(text: str):
    return YAML(typ="safe").load(text)


def test_new_file():
    text = add_unit_test(None, "orders_unit_tests.yml", ITEM)
    data = _load(text)
    test = data["unit_tests"][0]
    assert test["given"][0]["input"] == "ref('raw_orders')"
    assert test["given"][0]["rows"] == [{"id": 1, "status": "completed", "day": "2024-01-01"}]
    assert test["given"][1] == {"input": "source('shop', 'customers')", "rows": []}
    assert test["expect"]["rows"][0] == {"id": 1, "state": "done", "amount": 3.5, "ok": True, "note": None}
    assert "  - name: orders_state\n" in text


def test_appends_key_after_models():
    text = add_unit_test(SCHEMA, "schema.yml", ITEM)
    assert text.startswith(SCHEMA)
    data = _load(text)
    assert data["models"][0]["columns"][0]["data_tests"] == ["unique"]
    assert data["unit_tests"][0]["name"] == "orders_state"


def test_appends_to_existing_unit_tests_with_zero_offset():
    existing = "version: 2\n\nmodels:\n- name: orders\n  columns:\n  - name: id\n" + (
        "\nunit_tests:\n- name: old\n  model: orders\n  given: []\n  expect:\n    rows: []\n"
        "\n# trailing comment\n"
    )
    text = add_unit_test(existing, "schema.yml", ITEM)
    data = _load(text)
    assert [t["name"] for t in data["unit_tests"]] == ["old", "orders_state"]
    assert "\n- name: orders_state\n" in text


def test_unit_tests_before_another_key():
    existing = "version: 2\nunit_tests:\n  - name: old\n    model: orders\n    given: []\n    expect:\n      rows: []\nmodels:\n  - name: orders\n"
    data = _load(add_unit_test(existing, "schema.yml", ITEM))
    assert [t["name"] for t in data["unit_tests"]] == ["old", "orders_state"]
    assert data["models"] == [{"name": "orders"}]


def test_duplicate_name_refused():
    text = add_unit_test(SCHEMA, "schema.yml", ITEM)
    with pytest.raises(SchemaYamlError):
        add_unit_test(text, "schema.yml", ITEM)


def test_csv_format():
    item = {**ITEM, "given": [{"input": "ref('raw_orders')", "rows": [{"id": 1, "status": "a, b"}], "format": "csv"}]}
    data = _load(add_unit_test(None, "x.yml", item))
    given = data["unit_tests"][0]["given"][0]
    assert given["format"] == "csv"
    assert given["rows"] == 'id,status\n1,"a, b"\n'


def test_overrides_written():
    item = {**ITEM, "overrides": {"macros": {"is_incremental": True}}}
    data = _load(add_unit_test(None, "x.yml", item))
    assert data["unit_tests"][0]["overrides"] == {"macros": {"is_incremental": True}}


def test_flow_row_quoting():
    assert flow_row({"a": "plain", "b": "two words", "c": "yes", "d": "1", "e": None, "f": 2}) == (
        '{a: plain, b: "two words", c: "yes", d: "1", e: null, f: 2}'
    )


REBASE = """version: 2
unit_tests:
  - name: orders_state
    model: orders
    given:
      - input: ref('raw_orders')
        rows:
          - {id: 1}
    expect:
      rows:
        - {id: 1, state: open}
        - {id: 2, state: back}
      # keep me
  - name: other
    model: orders
    given: []
    expect:
      rows: []
"""


def test_replace_expect_rows():
    text = replace_expect_rows(REBASE, "schema.yml", "orders_state", [{"id": 1, "state": "done"}])
    data = _load(text)
    assert data["unit_tests"][0]["expect"]["rows"] == [{"id": 1, "state": "done"}]
    assert data["unit_tests"][1]["name"] == "other"
    assert "# keep me" in text


def test_replace_inline_empty_rows_and_last_entry():
    text = replace_expect_rows(REBASE, "schema.yml", "other", [{"id": 3}])
    assert _load(text)["unit_tests"][1]["expect"]["rows"] == [{"id": 3}]
    text = replace_expect_rows(text, "schema.yml", "other", [])
    assert _load(text)["unit_tests"][1]["expect"]["rows"] == []


def test_replace_refuses_csv_and_missing():
    csv_text = REBASE.replace("    expect:\n      rows:\n        - {id: 1, state: open}\n        - {id: 2, state: back}\n",
                              "    expect:\n      format: csv\n      rows: |\n        id\n        1\n")
    with pytest.raises(SchemaYamlError):
        replace_expect_rows(csv_text, "schema.yml", "orders_state", [{"id": 1}])
    with pytest.raises(SchemaYamlError):
        replace_expect_rows(REBASE, "schema.yml", "nope", [])
